//! 🧪️ Serde agrees with the defining semantic loan and exact physical/work conservation.
use super::*;
#[test]
fn original_actor_semantic_loan_preserves_exact_source_total_and_cutoff(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let input:RetainedTurnInput=serde_json::from_value(corpus["input"].clone()).unwrap();let loan:OriginalActorTurnLoan=serde_json::from_value(corpus["loan"].clone()).unwrap();let spent:RetainedCloneProgress=serde_json::from_value(corpus["spent"].clone()).unwrap();let work=corpus["workUnitsSpent"].as_u64().unwrap();let expected:OriginalActorTurnLoan=serde_json::from_value(corpus["remainingLoan"].clone()).unwrap();let((remaining,receipt),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{loan.validate_for(input).unwrap();(loan.remaining(spent,work).unwrap(),input.return_original(spent,work).unwrap())});assert_eq!(remaining,expected);assert_eq!(receipt.remaining_fuel,corpus["totalRemainingWork"].as_u64().unwrap());assert!(loan.remaining(spent,corpus["rawLoanWorkRefused"].as_u64().unwrap()).is_err());assert!(OriginalActorTurnLoan{work_fuel:input.work.fuel+1,..loan}.validate_for(input).is_err());assert!(OriginalActorTurnLoan{deadline_us:input.work.absolute_deadline_us+1,..loan}.validate_for(input).is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(serde_json::to_value(remaining).unwrap(),corpus["remainingLoan"]);}
